{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 Bucket Public Access Block Missing",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "HIGH",
      "explanation": "The S3 bucket does not have a public access block configured, leaving it potentially exposed to unauthorized public access if ACLs or policies are misconfigured."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 Bucket Access Logging Disabled",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "MEDIUM",
      "explanation": "Server access logging is not enabled for the bucket, which prevents auditing of requests made against the bucket and hinders incident response."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 Bucket Versioning Disabled",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "MEDIUM",
      "explanation": "Versioning is not enabled on the bucket, meaning accidental deletions or overwrites cannot be recovered from previous versions."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "bucket_2" {
  bucket = "roger-bucket-2"
  acl    = var.bucket_acl
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        kms_master_key_id = aws_kms_key.my_key.arn
        sse_algorithm     = "aws:kms"
      }
    }
  }
}

resource "aws_s3_bucket_public_access_block" "bucket_2" {
  bucket                  = aws_s3_bucket.bucket_2.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "bucket_2" {
  bucket        = aws_s3_bucket.bucket_2.id
  target_bucket = aws_s3_bucket.log_bucket.id
  target_prefix = "log/"
}

resource "aws_s3_bucket_versioning" "bucket_2" {
  bucket = aws_s3_bucket.bucket_2.id
  versioning_configuration {
    status = "Enabled"
  }
}",
  "fix_summary": "Added `aws_s3_bucket_public_access_block` to prevent public exposure, `aws_s3_bucket_logging` to enable access logs (assuming a log bucket exists), and `aws_s3_bucket_versioning` to enable versioning for data protection. Note: The logging resource references `aws_s3_bucket.log_bucket`, which must exist in the state; if not, this should be adjusted to point to an existing log destination."
}
